const fs = require("fs");
const vm = require("vm");

const source = fs.readFileSync(process.argv[2], "utf8");
const rafQueue = [];
const elements = new Map();

function classList() {
  const values = new Set();
  return {
    toggle(name, enabled) { enabled ? values.add(name) : values.delete(name); },
    contains(name) { return values.has(name); },
  };
}

function element(id) {
  if (elements.has(id)) return elements.get(id);
  const value = {
    id,
    textContent: "",
    hidden: id === "result",
    style: {},
    classList: classList(),
    attributes: {},
    setAttribute(name, content) { this.attributes[name] = content; },
  };
  elements.set(id, value);
  return value;
}

const track = element("tide-track");
const bar = element("tide-bar");
bar.parentElement = track;
const canvas = element("game");
canvas.width = 480;
canvas.height = 320;
canvas.getContext = () => ({
  clearRect() {}, fillRect() {}, beginPath() {}, arc() {}, fill() {}, fillStyle: "",
});

const context = {
  console,
  Math,
  clearInterval() {},
  document: { getElementById: element },
  window: { addEventListener() {} },
  performance: { now: () => 0 },
  requestAnimationFrame(callback) { rafQueue.push(callback); },
};
vm.createContext(context);
vm.runInContext(source, context, { filename: process.argv[2] });

const tide = element("tide");
const status = element("tide-status");
const hud = element("hud");
const result = element("result");
console.log(`initial tide=${tide.textContent} aria=${track.attributes["aria-valuenow"]} width=${bar.style.width}`);

function advanceFrame(nowMs) {
  const callback = rafQueue.shift();
  if (!callback) throw new Error("missing RAF callback");
  callback(nowMs);
}

advanceFrame(50);
console.log(`decrement tide=${tide.textContent} aria=${track.attributes["aria-valuenow"]} width=${bar.style.width}`);
for (let frame = 2; frame <= 800; frame += 1) advanceFrame(frame * 50);
console.log(`pt01@40s tide=${tide.textContent} urgentStatus=${status.classList.contains("urgent")} urgentHud=${hud.classList.contains("urgent")} label=${status.textContent}`);
for (let frame = 801; frame <= 1000; frame += 1) advanceFrame(frame * 50);
console.log(`settled@50s tide=${tide.textContent} aria=${track.attributes["aria-valuenow"]} hidden=${result.hidden} result=${result.textContent}`);
const settledSnapshot = `${tide.textContent}|${track.attributes["aria-valuenow"]}|${result.hidden}|${result.textContent}`;
for (let frame = 1001; frame <= 1005; frame += 1) advanceFrame(frame * 50);
const afterSnapshot = `${tide.textContent}|${track.attributes["aria-valuenow"]}|${result.hidden}|${result.textContent}`;
console.log(`idempotent=${settledSnapshot === afterSnapshot} after=${afterSnapshot}`);
if (tide.textContent !== "0" || result.hidden || /失败|输|lose|fail/i.test(result.textContent) || settledSnapshot !== afterSnapshot) process.exitCode = 1;
